using System.Windows;
using System.Windows.Documents;
using System.Windows.Media;

namespace ColumnView;

/// <summary>
/// アイコン 1 つ。Glyph には Segoe Fluent Icons 由来のコードポイント (例 "&#xE72B;") を目印として渡し、
/// 対応する Phosphor Icons (Light) の線画を描く。フォントに頼らないので、どの環境でも同じ見た目になる。
/// 色と大きさは文字と同じく Foreground / FontSize を親から受け継ぐ。
/// </summary>
public sealed class Icon : FrameworkElement
{
    public static readonly DependencyProperty GlyphProperty = DependencyProperty.Register(
        nameof(Glyph), typeof(string), typeof(Icon),
        new FrameworkPropertyMetadata("", FrameworkPropertyMetadataOptions.AffectsRender));

    public static readonly DependencyProperty ForegroundProperty = TextElement.ForegroundProperty.AddOwner(
        typeof(Icon), new FrameworkPropertyMetadata(Brushes.Black,
            FrameworkPropertyMetadataOptions.Inherits | FrameworkPropertyMetadataOptions.AffectsRender));

    public static readonly DependencyProperty FontSizeProperty = TextElement.FontSizeProperty.AddOwner(
        typeof(Icon), new FrameworkPropertyMetadata(12.0,
            FrameworkPropertyMetadataOptions.Inherits | FrameworkPropertyMetadataOptions.AffectsMeasure
            | FrameworkPropertyMetadataOptions.AffectsRender));

    public string Glyph { get => (string)GetValue(GlyphProperty); set => SetValue(GlyphProperty, value); }
    public Brush Foreground { get => (Brush)GetValue(ForegroundProperty); set => SetValue(ForegroundProperty, value); }
    public double FontSize { get => (double)GetValue(FontSizeProperty); set => SetValue(FontSizeProperty, value); }

    // 線画は字形より余白が多いので、同じ FontSize で見た目の大きさがそろうよう少し大きめの枠に描く
    const double BoxScale = 1.15;
    const double ViewBox = 256;

    double Box => Math.Round(FontSize * BoxScale);

    protected override Size MeasureOverride(Size availableSize) => new(Box, Box);

    protected override void OnRender(DrawingContext dc)
    {
        var glyph = Glyph;
        if (string.IsNullOrEmpty(glyph)) return;
        var shape = Lookup(char.ConvertToUtf32(glyph, 0));
        if (shape is null) return;
        double box = Box;
        double k = box / ViewBox;
        // 横に引き伸ばされた (Stretch) ときは TextBlock と同じく左寄せで描く
        dc.PushTransform(new MatrixTransform(k, 0, 0, k, 0, (ActualHeight - box) / 2));
        dc.DrawGeometry(Foreground, null, shape);
        dc.Pop();
    }

    // 形は初めて使うときに作り、以降は凍結したものを使い回す
    static readonly Dictionary<int, Geometry> Cache = new();

    static Geometry? Lookup(int code)
    {
        if (Cache.TryGetValue(code, out var g)) return g;
        if (!Paths.TryGetValue(code, out var data)) return null;
        g = Geometry.Parse(data);
        g.Freeze();
        Cache[code] = g;
        return g;
    }

